238	function sameObservation(left: ContextObservation, right: ContextObservation): boolean {
239	  if (!sameGuardedRead(left.config, right.config)) return false;
240	  if (left.documents.size !== right.documents.size) return false;
241	  for (const [id, read] of left.documents) {
242	    const other = right.documents.get(id);
243	    if (other === undefined || !sameGuardedRead(read, other)) return false;
244	  }
245	  return true;
246	}
